// Custom next/image loader: serves variants pre-generated by scripts/optimize-images.mjs.
// URLs end in .webp; next.config rewrites them to the matching .avif for browsers that accept AVIF.
// Vercel performs zero image transformations. Remote and non raster images pass through untouched.
import manifest from "./lib/image-manifest.json";

const variants = manifest as unknown as Record<string, [string, ...number[]]>;

export default function imageLoader({ src, width }: { src: string; width: number; quality?: number }) {
  if (!src.startsWith("/") || src.startsWith("//")) return src;
  const clean = src.split(/[?#]/)[0];
  let key = clean;
  try {
    key = decodeURI(clean);
  } catch {}
  const entry = variants[key];
  if (!entry) return src;
  const [hash, ...widths] = entry;
  const w = widths.find((x) => x >= width) ?? widths[widths.length - 1];
  return encodeURI(`/_opt${key.replace(/\.(jpe?g|png|webp)$/i, "")}.${hash}-${w}.webp`);
}
